namespace sv_15c5c03de1f543c8866635312da8bae5.Services;

public class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        Warehouses.TryGetValue(_currentWarehouseId, out var name) ? name : _currentWarehouseId;

    public static readonly Dictionary<string, string> Warehouses = new()
    {
        ["WH-001"] = "Warehouse A — Main Distribution",
        ["WH-002"] = "Warehouse B — East Region",
        ["WH-003"] = "Warehouse C — West Region",
        ["WH-004"] = "Warehouse D — Returns Processing"
    };

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        OnChange = null;
    }
}

namespace sv_15c5c03de1f543c8866635312da8bae5.Services;

public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _lastLowStockCount;

    public int LastLowStockCount => _lastLowStockCount;

    /// <summary>
    /// Raised whenever new alert data has been fetched. Subscribers should
    /// call InvokeAsync(StateHasChanged) to re-render.
    /// </summary>
    public event Action? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query that returns the number of items below
    /// minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with a random result 0–15.
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches fresh alert data and notifies all subscribers.
    /// Called by whichever component owns the polling timer.
    /// </summary>
    public async Task RefreshAlertDataAsync(string warehouseId)
    {
        _lastLowStockCount = await GetLowStockCountAsync(warehouseId);
        OnAlertDataChanged?.Invoke();
    }

    public void Dispose()
    {
        OnAlertDataChanged = null;
    }
}

