+@page "/dashboard"
+@rendermode InteractiveServer
+@inject WarehouseStateService WarehouseState
+@inject InventoryAlertService AlertService
+@implements IDisposable
+
+<PageTitle>Dashboard</PageTitle>
+
+<h1>Warehouse Dashboard</h1>
+
+<div class="card mb-4" style="max-width: 500px;">
+    <div class="card-body">
+        <h5 class="card-title">Current Warehouse</h5>
+        <p class="card-text fs-5">@WarehouseState.CurrentWarehouseName</p>
+    </div>
+</div>
+
+<div class="card mb-4" style="max-width: 500px;">
+    <div class="card-body">
+        <h5 class="card-title">
+            Low-Stock Alerts
+            <span class="badge @BadgeClass ms-2">@AlertService.LastLowStockCount</span>
+        </h5>
+        <p class="card-text text-muted">
+            Polling every 10 seconds for items below minimum stock levels.
+        </p>
+    </div>
+</div>
+
+@code {
+    private CancellationTokenSource? _cts;
+
+    private string BadgeClass => AlertService.LastLowStockCount switch
+    {
+        > 10 => "bg-danger",
+        > 5 => "bg-warning text-dark",
+        > 0 => "bg-info",
+        _ => "bg-secondary"
+    };
+
+    protected override async Task OnInitializedAsync()
+    {
+        WarehouseState.OnChange += OnWarehouseChanged;
+        AlertService.OnAlertDataChanged += OnAlertDataChanged;
+
+        // Fetch initial data, then start polling.
+        await AlertService.RefreshAlertDataAsync(WarehouseState.CurrentWarehouseId);
+        StartPolling();
+    }
+
+    private void StartPolling()
+    {
+        StopPolling();
+        _cts = new CancellationTokenSource();
+        _ = PollLoopAsync(_cts.Token);
+    }
+
+    private void StopPolling()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = null;
+    }
+
+    private async Task PollLoopAsync(CancellationToken ct)
+    {
+        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
+        try
+        {
+            while (await timer.WaitForNextTickAsync(ct))
+            {
+                await AlertService.RefreshAlertDataAsync(WarehouseState.CurrentWarehouseId);
+            }
+        }
+        catch (OperationCanceledException) { }
+    }
+
+    private void OnWarehouseChanged()
+    {
+        InvokeAsync(async () =>
+        {
+            // Immediately refresh data for the newly selected warehouse,
+            // then restart the polling interval.
+            await AlertService.RefreshAlertDataAsync(WarehouseState.CurrentWarehouseId);
+            StartPolling();
+            StateHasChanged();
+        });
+    }
+
+    private void OnAlertDataChanged()
+    {
+        InvokeAsync(StateHasChanged);
+    }
+
+    public void Dispose()
+    {
+        StopPolling();
+        WarehouseState.OnChange -= OnWarehouseChanged;
+        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
+    }
+}
+

